process SCIMAP_MCMICRO {
    tag "$meta.id"
    label 'process_single'

    // WARN: Version information not provided by tool on CLI. Please update version string below when bumping container versions.
    container "docker.io/labsyspharm/scimap:2.1.3"

    input:
    tuple val(meta), path(cellbyfeature)

    output:
    tuple val(meta), path("*.csv")      , emit: csv     , optional:true
    tuple val(meta), path("*.h5ad")     , emit: h5ad    , optional:true
    tuple val("${task.process}"), val('scimap'), val('2.1.3'), topic: versions, emit: versions_scimap
    // WARN: Version information not provided by tool on CLI. Please update this string when bumping container versions.

    when:
    task.ext.when == null || task.ext.when

    script:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "Scimap module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    """
    mkdir numba_cache_dir
    export NUMBA_CACHE_DIR='./numba_cache_dir'

    scimap-mcmicro $cellbyfeature -o .
    """

    stub:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "Scimap module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    """
    touch ${cellbyfeature.baseName}.h5ad.csv
    touch ${cellbyfeature.baseName}.h5ad
    """

}

nextflow_process {

    name "Test Process SCIMAP_MCMICRO"
    script "../main.nf"
    process "SCIMAP_MCMICRO"

    tag "modules"
    tag "modules_nfcore"
    tag "scimap"
    tag "scimap/mcmicro"

    test("test-scimap-mcmicro") {

        when {
            process {
                """
                input[0] = [
				    [ id:'test' ], // meta map
				    file(params.modules_testdata_base_path + 'imaging/downstream/cycif_tonsil_cell.csv', checkIfExists: true)
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.csv[0][1]).readLines()[0],
                    file(process.out.h5ad[0][1]).name,
                    sanitizeOutput(process.out, unstableKeys: ["csv", "h5ad"])
                    ).match()
                }
            )
        }
    }

    test("test-scimap-mcmicro-stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
				    [ id:'test' ], // meta map
				    file(params.modules_testdata_base_path + 'imaging/downstream/cycif_tonsil_cell.csv', checkIfExists: true)
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}
